/*
 * General_Category lookups for layout (W4f): the characters ::first-letter includes around the first letter
 * (CSS Pseudo 4: punctuation of the classes Ps, Pe, Pi, Pf, Po, and the combining marks of the letter). The ranges
 * are a compact layout-only table (charclass_data.inc, ~10 KB, generated by tools/layoutgen/charclass.py from the
 * UCD), so layout depends neither on the js module nor on its large Unicode tables.
 */
#include "layout_int.h"

#include "charclass_data.inc"

static bool in_ranges(const uint32_t (*r)[2], size_t n, uint32_t cp)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (cp < r[mid][0]) {
            hi = mid;
        } else if (cp > r[mid][1]) {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

bool embi_lay_is_fl_punct(uint32_t cp)
{
    if (cp < 0x80) {
        /* The ASCII punctuation of the classes Ps, Pe, Po (not Pc, Pd, Sm, Sc, Sk). */
        switch (cp) {
        case '!': case '"': case '#': case '%': case '&': case '\'': case '(': case ')': case '*': case ',':
        case '.': case '/': case ':': case ';': case '?': case '@': case '[': case 0x5C: case ']': case '{':
        case '}':
            return true;
        default:
            return false;
        }
    }
    return in_ranges(k_fl_punct, SDL_arraysize(k_fl_punct), cp);
}

bool embi_lay_is_mark(uint32_t cp)
{
    return cp >= 0x300 && in_ranges(k_marks, SDL_arraysize(k_marks), cp);
}
